    Check 1: a department_id that matches at least one row.

    The expected value is computed independently by a separate COUNT(*) using
    the same predicate used inside the function:
      WHERE department_id = p_department_id
  */
  SELECT MIN(department_id)
    INTO l_matching_department_id
    FROM harness_app.employees
   WHERE department_id IS NOT NULL;

  IF l_matching_department_id IS NULL THEN
    DBMS_OUTPUT.PUT_LINE(
      'FAIL matching-key: expected a non-NULL department_id to test, actual MIN(department_id) is NULL'
    );
    l_failures := l_failures + 1;
  ELSE
    SELECT COUNT(*)
      INTO l_expected
      FROM harness_app.employees
     WHERE department_id = l_matching_department_id;

    l_actual := harness_app.headcount(l_matching_department_id);

    IF l_expected = l_actual THEN
