    ELSE
      DBMS_OUTPUT.PUT_LINE(
        'FAIL matching-key: expected=' || TO_CHAR(l_expected) ||
        ', actual=' || TO_CHAR(l_actual) ||
        ', department_id=' || TO_CHAR(l_matching_department_id)
